PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS companies(id TEXT PRIMARY KEY, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, salt TEXT NOT NULL, password_hash TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0, failures INTEGER NOT NULL DEFAULT 0, locked_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS memberships(user_id TEXT REFERENCES users(id), company_id TEXT REFERENCES companies(id), role TEXT NOT NULL CHECK(role IN ('owner','preparer','reviewer','viewer')), PRIMARY KEY(user_id,company_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS objects(company_id TEXT NOT NULL REFERENCES companies(id),kind TEXT NOT NULL,id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),body TEXT NOT NULL CHECK(json_valid(body)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(company_id,kind,id));
CREATE INDEX IF NOT EXISTS objects_company_kind ON objects(company_id,kind);
CREATE INDEX IF NOT EXISTS event_fact_lookup ON objects(company_id,json_extract(body,'$.event_id'),json_extract(body,'$.context_hash')) WHERE kind='event_fact';
CREATE INDEX IF NOT EXISTS source_record_document_lookup ON objects(company_id,json_extract(body,'$.document_id')) WHERE kind='source_record';
CREATE INDEX IF NOT EXISTS settlement_payment_lookup ON objects(company_id,json_extract(body,'$.payment_id')) WHERE kind='event_settlement';
CREATE TABLE IF NOT EXISTS blobs(company_id TEXT NOT NULL REFERENCES companies(id),id TEXT NOT NULL,sha256 TEXT NOT NULL,filename TEXT NOT NULL,mime TEXT NOT NULL,content BLOB NOT NULL,text_content TEXT,extraction_status TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(company_id,id),UNIQUE(company_id,sha256));
CREATE TABLE IF NOT EXISTS external_ids(company_id TEXT NOT NULL REFERENCES companies(id),namespace TEXT NOT NULL,external_id TEXT NOT NULL,body_hash TEXT NOT NULL,object_id TEXT NOT NULL,PRIMARY KEY(company_id,namespace,external_id));
CREATE TABLE IF NOT EXISTS audit(seq INTEGER PRIMARY KEY AUTOINCREMENT,company_id TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,at TEXT NOT NULL,detail TEXT NOT NULL,previous_hash TEXT NOT NULL,event_hash TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_company_seq ON audit(company_id,seq);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'AUDIT_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'AUDIT_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS posted_journal_no_update BEFORE UPDATE ON objects WHEN OLD.kind='journal' AND json_extract(OLD.body,'$.state')='POSTED' BEGIN SELECT RAISE(ABORT,'POSTED_JOURNAL_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS posted_journal_no_delete BEFORE DELETE ON objects WHEN OLD.kind='journal' AND json_extract(OLD.body,'$.state')='POSTED' BEGIN SELECT RAISE(ABORT,'POSTED_JOURNAL_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS blob_no_update BEFORE UPDATE ON blobs BEGIN SELECT RAISE(ABORT,'EVIDENCE_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS blob_no_delete BEFORE DELETE ON blobs BEGIN SELECT RAISE(ABORT,'EVIDENCE_IMMUTABLE'); END;
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),transaction_id TEXT NOT NULL,input_revision INTEGER NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0,result TEXT,error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(company_id,transaction_id,input_revision));
CREATE TABLE IF NOT EXISTS object_history(company_id TEXT NOT NULL,kind TEXT NOT NULL,id TEXT NOT NULL,revision INTEGER NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,archived_at TEXT NOT NULL,PRIMARY KEY(company_id,kind,id,revision));
CREATE TRIGGER IF NOT EXISTS object_revision_archive BEFORE UPDATE ON objects BEGIN INSERT INTO object_history(company_id,kind,id,revision,body,created_at,updated_at,archived_at) VALUES(OLD.company_id,OLD.kind,OLD.id,OLD.revision,OLD.body,OLD.created_at,OLD.updated_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER IF NOT EXISTS history_no_update BEFORE UPDATE ON object_history BEGIN SELECT RAISE(ABORT,'HISTORY_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS history_no_delete BEFORE DELETE ON object_history BEGIN SELECT RAISE(ABORT,'HISTORY_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS stock_movement_no_update BEFORE UPDATE ON objects WHEN OLD.kind='stock_movement' BEGIN SELECT RAISE(ABORT,'STOCK_MOVEMENT_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS stock_movement_no_delete BEFORE DELETE ON objects WHEN OLD.kind='stock_movement' BEGIN SELECT RAISE(ABORT,'STOCK_MOVEMENT_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS automation_effect_no_update BEFORE UPDATE ON objects WHEN OLD.kind='automation_effect' BEGIN SELECT RAISE(ABORT,'AUTOMATION_EFFECT_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS automation_effect_no_delete BEFORE DELETE ON objects WHEN OLD.kind='automation_effect' BEGIN SELECT RAISE(ABORT,'AUTOMATION_EFFECT_IMMUTABLE'); END;
CREATE INDEX IF NOT EXISTS automation_effect_grant ON objects(company_id,json_extract(body,'$.grant_id')) WHERE kind='automation_effect';
CREATE UNIQUE INDEX IF NOT EXISTS posted_schedule_entry_unique ON objects(company_id,json_extract(body,'$.book_schedule_id'),json_extract(body,'$.book_schedule_key')) WHERE kind='journal' AND json_extract(body,'$.state')='POSTED' AND json_extract(body,'$.book_schedule_id') IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS posted_stock_entry_unique ON objects(company_id,json_extract(body,'$.inventory_reference')) WHERE kind='journal' AND json_extract(body,'$.state')='POSTED' AND json_extract(body,'$.inventory_reference') IS NOT NULL;
